import java.sql.*;
import java.nio.file.*;
import java.util.*;
import com.fasterxml.jackson.databind.ObjectMapper;

/** SELECT-only inspection. Oracle enforces READ ONLY for the entire transaction. */
public class OracleAssistantStatementsLoansReadAudit {
 public static void main(String[] args)throws Exception{
  var queries=new LinkedHashMap<String,String>();
  queries.put("loanProducts","SELECT P.PRODUCT_CODE,P.PRODUCT_ID,V.PRODUCT_VERSION_ID,R.MIN_LOAN_AMOUNT,R.MAX_LOAN_AMOUNT,R.MIN_TENURE_MONTHS,R.MAX_TENURE_MONTHS,R.ALLOWED_INTEREST_TYPE,R.REPAYMENT_FREQUENCY,R.AMORTIZATION_METHOD,R.DISBURSEMENT_MODE,R.PREPAYMENT_ALLOWED,R.PARTIAL_PREPAYMENT_ALLOWED,R.FORECLOSURE_ALLOWED,(SELECT COUNT(DISTINCT M.GL_ROLE_CODE) FROM M05_GL_PRODUCT_MAPPING M WHERE M.PRODUCT_VERSION_ID=V.PRODUCT_VERSION_ID AND M.POSTING_TYPE='LOAN' AND M.STATUS='ACTIVE' AND M.GL_ROLE_CODE IN ('LOAN_PRINCIPAL','LOAN_INTEREST','INTEREST_INCOME')) GL_ROLES FROM M03_PM_PRODUCT P JOIN M03_PM_PRODUCT_VERSION V ON V.PRODUCT_ID=P.PRODUCT_ID LEFT JOIN M03_PM_LOAN_RULE R ON R.PRODUCT_VERSION_ID=V.PRODUCT_VERSION_ID WHERE P.PRODUCT_TYPE='LOAN' AND V.VERSION_STATE='ACTIVE' ORDER BY P.PRODUCT_CODE");
  queries.put("loanInterestRules","SELECT P.PRODUCT_CODE,R.INTEREST_TYPE,R.INTEREST_METHOD,R.FIXED_RATE_PCT,R.DAY_COUNT_BASIS,R.COMPOUND_FREQUENCY,R.PAYOUT_FREQUENCY,R.ROUNDING_MODE FROM M03_PM_PRODUCT P JOIN M03_PM_PRODUCT_VERSION V ON V.PRODUCT_ID=P.PRODUCT_ID JOIN M03_PM_INTEREST_RULE R ON R.PRODUCT_VERSION_ID=V.PRODUCT_VERSION_ID WHERE P.PRODUCT_TYPE='LOAN' AND V.VERSION_STATE='ACTIVE'");
  queries.put("loanCheckerAssignments","SELECT U.USERNAME,R.ROLE_CODE,A.SCOPE_TYPE,A.SCOPE_REF FROM M01_IAM_USER U JOIN M01_IAM_USER_ROLE A ON A.USER_ID=U.USER_ID JOIN M01_IAM_ROLE R ON R.ROLE_ID=A.ROLE_ID WHERE U.STATUS='ACTIVE' AND U.USER_TYPE='EMPLOYEE' AND R.ROLE_CODE IN ('BANK_ADMIN','BANK_CHECKER') AND A.STATUS='ACTIVE' AND A.VALID_FROM<=SYSTIMESTAMP AND (A.VALID_TO IS NULL OR A.VALID_TO>SYSTIMESTAMP) ORDER BY U.USERNAME");
  queries.put("loanAuthorities","SELECT R.ROLE_CODE,A.AUTHORITY_CODE,A.CURRENCY_CODE,A.MAX_AMOUNT,A.MAX_RATE_PCT FROM M01_IAM_ROLE_AUTHORITY A JOIN M01_IAM_ROLE R ON R.ROLE_ID=A.ROLE_ID WHERE A.AUTHORITY_CODE='LOAN_SANCTION' AND A.VALID_FROM<=SYSTIMESTAMP AND (A.VALID_TO IS NULL OR A.VALID_TO>SYSTIMESTAMP)");
  queries.put("loanRolePermissions","SELECT R.ROLE_CODE,P.PERMISSION_CODE FROM M01_IAM_ROLE R JOIN M01_IAM_ROLE_PERMISSION RP ON RP.ROLE_ID=R.ROLE_ID JOIN M01_IAM_PERMISSION P ON P.PERMISSION_ID=RP.PERMISSION_ID WHERE R.ROLE_CODE IN ('BANK_ADMIN','BANK_CHECKER','BANK_CUSTOMER') AND P.PERMISSION_CODE LIKE 'LOAN_%' ORDER BY R.ROLE_CODE,P.PERMISSION_CODE");
  queries.put("depositLoanMappings","SELECT A.PRODUCT_VERSION_ID,COUNT(*) ACTIVE_ACCOUNTS,(SELECT COUNT(*) FROM M05_GL_PRODUCT_MAPPING M WHERE M.PRODUCT_VERSION_ID=A.PRODUCT_VERSION_ID AND M.POSTING_TYPE='LOAN' AND M.GL_ROLE_CODE='CUSTOMER_LIABILITY' AND M.STATUS='ACTIVE') LIABILITY_MAPPINGS FROM M04_BANK_ACCOUNT A WHERE A.LIFECYCLE_STATUS='ACTIVE' GROUP BY A.PRODUCT_VERSION_ID");
  queries.put("loanApplicationStates","SELECT STATUS,COUNT(*) ROW_COUNT FROM M08_LOAN_APPLICATION GROUP BY STATUS");
  queries.put("loanFacilityStates","SELECT STATUS,COUNT(*) ROW_COUNT FROM M08_LOAN_FACILITY GROUP BY STATUS");
  queries.put("loanDisbursementStates","SELECT STATUS,FAILURE_CODE,COUNT(*) ROW_COUNT FROM M08_LOAN_DISBURSEMENT GROUP BY STATUS,FAILURE_CODE");
  queries.put("loanPaymentStates","SELECT STATUS,COUNT(*) ROW_COUNT FROM M08_LOAN_PAYMENT GROUP BY STATUS");
  queries.put("loanFacilities","SELECT FACILITY_ID,APPLICATION_ID,PRINCIPAL_AMOUNT,TOTAL_DISBURSED_AMOUNT,PRINCIPAL_OUTSTANDING,INTEREST_OUTSTANDING,TENURE_MONTHS,ANNUAL_RATE_PCT,STATUS FROM M08_LOAN_FACILITY ORDER BY FACILITY_ID");
  queries.put("statementPolicies","SELECT CHANNEL_CODE,AUDIENCE_CODE,STATUS,COUNT(*) ROW_COUNT FROM M10_MASKING_PROFILE GROUP BY CHANNEL_CODE,AUDIENCE_CODE,STATUS");
  queries.put("statementNarrations","SELECT NARRATION_CODE,LOCALE_CODE,AUDIENCE_CODE,APPROVAL_STATUS,COUNT(*) ROW_COUNT FROM M10_NARRATION_CATALOG WHERE EFFECTIVE_FROM<=SYSTIMESTAMP AND (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>SYSTIMESTAMP) GROUP BY NARRATION_CODE,LOCALE_CODE,AUDIENCE_CODE,APPROVAL_STATUS");
  queries.put("statementPurposes","SELECT PURPOSE_CODE,STATUS,OWNER_SERVICE,CASE WHEN EFFECTIVE_FROM<=SYSTIMESTAMP AND (EFFECTIVE_TO IS NULL OR EFFECTIVE_TO>SYSTIMESTAMP) THEN 'Y' ELSE 'N' END CURRENTLY_EFFECTIVE FROM M09_PRIVACY_PROCESSING_PURPOSE WHERE OWNER_SERVICE='M10_STATEMENTS'");
  queries.put("statementRequestStates","SELECT REQUESTER_TYPE,STATUS,FAILURE_CODE,COUNT(*) ROW_COUNT FROM M10_STATEMENT_REQUEST GROUP BY REQUESTER_TYPE,STATUS,FAILURE_CODE");
  queries.put("statementSnapshotStates","SELECT STATE,RESOLVED_LOCALE,COUNT(*) ROW_COUNT FROM M10_STATEMENT_SNAPSHOT GROUP BY STATE,RESOLVED_LOCALE");
  var checks=new LinkedHashMap<String,String>();
  checks.put("loan facility totals match posted disbursements","SELECT COUNT(*) FROM M08_LOAN_FACILITY F WHERE F.TOTAL_DISBURSED_AMOUNT<>NVL((SELECT SUM(D.AMOUNT) FROM M08_LOAN_DISBURSEMENT D WHERE D.FACILITY_ID=F.FACILITY_ID AND D.STATUS='POSTED'),0)");
  checks.put("loan approvals have independent checkers","SELECT COUNT(*) FROM M08_LOAN_DISBURSEMENT WHERE STATUS='POSTED' AND (APPROVED_BY_USER_ID IS NULL OR APPROVED_BY_USER_ID=REQUESTED_BY_USER_ID)");
  checks.put("posted disbursements have balanced journals","SELECT COUNT(*) FROM M08_LOAN_DISBURSEMENT D LEFT JOIN M05_V_GL_JOURNAL_CONTROL J ON J.JOURNAL_ID=D.GL_JOURNAL_ID WHERE D.STATUS='POSTED' AND (J.JOURNAL_ID IS NULL OR J.IS_BALANCED<>'Y')");
  checks.put("active facilities have one active schedule","SELECT COUNT(*) FROM M08_LOAN_FACILITY F WHERE F.STATUS IN ('ACTIVE','DELINQUENT') AND (SELECT COUNT(*) FROM M08_LOAN_SCHEDULE S WHERE S.FACILITY_ID=F.FACILITY_ID AND S.STATUS='ACTIVE')<>1");
  checks.put("schedule totals match installment sums","SELECT COUNT(*) FROM M08_LOAN_SCHEDULE S WHERE S.STATUS='ACTIVE' AND (S.INSTALLMENT_COUNT<>(SELECT COUNT(*) FROM M08_LOAN_SCHEDULE_ITEM I WHERE I.SCHEDULE_ID=S.SCHEDULE_ID) OR S.TOTAL_PRINCIPAL<>NVL((SELECT SUM(I.PRINCIPAL_DUE) FROM M08_LOAN_SCHEDULE_ITEM I WHERE I.SCHEDULE_ID=S.SCHEDULE_ID),0) OR S.TOTAL_INTEREST<>NVL((SELECT SUM(I.INTEREST_DUE) FROM M08_LOAN_SCHEDULE_ITEM I WHERE I.SCHEDULE_ID=S.SCHEDULE_ID),0))");
  checks.put("active loan principal agrees with schedule repayments","SELECT COUNT(*) FROM M08_LOAN_FACILITY F JOIN M08_LOAN_SCHEDULE S ON S.FACILITY_ID=F.FACILITY_ID AND S.STATUS='ACTIVE' WHERE F.PRINCIPAL_OUTSTANDING<>NVL((SELECT SUM(I.PRINCIPAL_DUE-I.PRINCIPAL_PAID-I.PRINCIPAL_WAIVED) FROM M08_LOAN_SCHEDULE_ITEM I WHERE I.SCHEDULE_ID=S.SCHEDULE_ID),0)");
  checks.put("loan projections agree with receivable ledger","SELECT COUNT(*) FROM M08_LOAN_FACILITY F WHERE F.PRINCIPAL_OUTSTANDING<>NVL((SELECT SUM(P.RECEIVABLE_BALANCE) FROM M05_V_LOAN_RECEIVABLE_POSITION P WHERE P.LOAN_FACILITY_ID=F.FACILITY_ID AND P.LOAN_COMPONENT_CODE='PRINCIPAL'),0) OR F.INTEREST_OUTSTANDING<>NVL((SELECT SUM(P.RECEIVABLE_BALANCE) FROM M05_V_LOAN_RECEIVABLE_POSITION P WHERE P.LOAN_FACILITY_ID=F.FACILITY_ID AND P.LOAN_COMPONENT_CODE='INTEREST'),0)");
  checks.put("existing facility terms meet current product bounds","SELECT COUNT(*) FROM M08_LOAN_FACILITY F JOIN M03_PM_LOAN_RULE R ON R.PRODUCT_VERSION_ID=F.PRODUCT_VERSION_ID WHERE F.PRINCIPAL_AMOUNT<R.MIN_LOAN_AMOUNT OR F.PRINCIPAL_AMOUNT>R.MAX_LOAN_AMOUNT OR F.TENURE_MONTHS<R.MIN_TENURE_MONTHS OR F.TENURE_MONTHS>R.MAX_TENURE_MONTHS");
  checks.put("payment allocations equal loan payment amount","SELECT COUNT(*) FROM M08_LOAN_PAYMENT P WHERE P.STATUS='ALLOCATED' AND P.AMOUNT<>NVL((SELECT SUM(A.AMOUNT) FROM M08_LOAN_PAYMENT_ALLOCATION A WHERE A.LOAN_PAYMENT_ID=P.LOAN_PAYMENT_ID),0)");
  checks.put("issued statements balance to signed lines","SELECT COUNT(*) FROM M10_STATEMENT_SNAPSHOT S WHERE S.STATE='ISSUED' AND (S.CLOSING_POSTED_BALANCE<>S.OPENING_POSTED_BALANCE+NVL((SELECT SUM(L.AMOUNT_SIGNED) FROM M10_STATEMENT_LINE_ITEM L WHERE L.STATEMENT_ID=S.STATEMENT_ID),0) OR S.SOURCE_TRANSACTION_COUNT<>(SELECT COUNT(*) FROM M10_STATEMENT_LINE_ITEM L WHERE L.STATEMENT_ID=S.STATEMENT_ID))");
  checks.put("statement running balances are consistent","SELECT COUNT(*) FROM (SELECT L.POSTED_BALANCE_AFTER,S.OPENING_POSTED_BALANCE+SUM(L.AMOUNT_SIGNED) OVER(PARTITION BY L.STATEMENT_ID ORDER BY L.LINE_NO ROWS UNBOUNDED PRECEDING) EXPECTED FROM M10_STATEMENT_LINE_ITEM L JOIN M10_STATEMENT_SNAPSHOT S ON S.STATEMENT_ID=L.STATEMENT_ID WHERE S.STATE='ISSUED') WHERE POSTED_BALANCE_AFTER<>EXPECTED");
  checks.put("completed requests have issued snapshots","SELECT COUNT(*) FROM M10_STATEMENT_REQUEST R WHERE R.STATUS='COMPLETED' AND NOT EXISTS(SELECT 1 FROM M10_STATEMENT_SNAPSHOT S WHERE S.REQUEST_ID=R.REQUEST_ID AND S.STATE='ISSUED')");
  var report=new LinkedHashMap<String,Object>();var results=new ArrayList<Map<String,Object>>();
  var props=new Properties();props.setProperty("user",System.getenv("DB_USERNAME"));props.setProperty("password",System.getenv("DB_PASSWORD"));props.setProperty("oracle.net.CONNECT_TIMEOUT","5000");props.setProperty("oracle.jdbc.ReadTimeout","15000");
  try(var db=DriverManager.getConnection(System.getenv("DB_URL"),props)){
   db.setAutoCommit(false);try(var s=db.createStatement()){s.execute("SET TRANSACTION READ ONLY");}
   try{
    for(var q:queries.entrySet()){try{var rows=rows(db,q.getValue());report.put(q.getKey(),rows);System.out.println(q.getKey()+": "+rows.size()+" rows");}catch(SQLException e){report.put(q.getKey(),Map.of("oracleErrorCode",e.getErrorCode()));System.out.println(q.getKey()+": Oracle error "+e.getErrorCode());}}
    for(var q:checks.entrySet()){try(var s=db.createStatement()){s.setQueryTimeout(30);try(var rs=s.executeQuery(q.getValue())){rs.next();long count=rs.getLong(1);var r=Map.<String,Object>of("name",q.getKey(),"exceptions",count,"status",count==0?"PASS":"FAIL");results.add(r);System.out.println(r);}}catch(SQLException e){results.add(Map.of("name",q.getKey(),"status","ERROR","oracleErrorCode",e.getErrorCode()));}}
   }finally{db.rollback();}
  }
  report.put("checkedAt",java.time.Instant.now().toString());report.put("databaseReadOnly",true);report.put("checks",results);new ObjectMapper().writerWithDefaultPrettyPrinter().writeValue(Path.of(args[0]).toFile(),report);
 }
 static List<Map<String,Object>> rows(Connection db,String sql)throws SQLException{
  var result=new ArrayList<Map<String,Object>>();try(var s=db.createStatement()){s.setQueryTimeout(30);try(var rs=s.executeQuery(sql)){var meta=rs.getMetaData();while(rs.next()){var row=new LinkedHashMap<String,Object>();for(int i=1;i<=meta.getColumnCount();i++){Object value=rs.getObject(i);row.put(meta.getColumnLabel(i),value instanceof Number?value:rs.getString(i));}result.add(row);}}}return result;
 }
}
